#!/bin/sh
# Rewrites the install section of the README (between the install markers)
# for a repository and a version: scripts/readme-install.sh owner/repo v1.2.0
set -eu
repo="$1"
version="$2"
raw="https://raw.githubusercontent.com/$repo/main/install.sh"
dl="https://github.com/$repo/releases"
section="$(mktemp)"
cat > "$section" <<SECTION
<!-- install:start (generated by the release workflow, see scripts/readme-install.sh) -->
Latest release: **$version** · [all releases]($dl)

Install or update (Linux, x86_64 or arm64):

\`\`\`sh
curl -fsSL $raw | sh
\`\`\`

The latest build of \`main\`: \`curl -fsSL $raw | sh -s -- edge\` · a given version: \`... | sh -s -- $version\`

Docker (linux amd64 / arm64): \`docker pull nbittich/artcoded-cli\`, see [Docker](#docker).
<!-- install:end -->
SECTION
awk -v f="$section" '
  /<!-- install:start/ { while ((getline l < f) > 0) print l; skip = 1; next }
  /<!-- install:end -->/ { skip = 0; next }
  !skip { print }
' README.md > README.md.new
mv README.md.new README.md
rm -f "$section"
